### Which @angular/* package(s) are the source of the bug?

core

### Is this a regression?

Yes

### Description

- when using jasmine it works fine
- it works runtime
- when using vitest I get `Error: NG0950: Input "orgId" is required but no value is available yet. Find more at https://v22.angular.dev/errors/NG0950`
- spec
```ts
it('should set orgId from url (using RouterTestingHarness)', async () => {
    const harness = await RouterTestingHarness.create();
    const instance = await harness.navigateByUrl(
      `/org?orgId=2`,
      OrgComponent
    );

    TestBed.tick();
    harness.detectChanges();

    expect(instance.orgId()!.toString()).toBe(2);
  });

it('should orgId', () => {
    const f = TestBed.createComponent(OrgComponent, {
      bindings: [inputBinding('orgId', () => 1)],
    });
    const c = f.componentInstance;
    f.detectChanges();

    expect(instance.orgId()!.toString()).toBe(2);
  });
```

- component

```ts
export default class OrgComponent implements OnInit {
  readonly orgId = input.required<number>(); // url param orgId
  readonly #toaster = inject(ToastService);

  readonly #effQuery = effect(() => {
    if (!this.orgId()) {
      this.#toaster.error({ type: 'text', text: 'Missing url parameter orgId' });
    }
  });
```

